// `sample.Strict.shapes` holds heap data inside heap data, so its
// round trip is not a Kani harness: copies out of nested heap memory
// are beyond the solver. Its parsing is proved by the validator
// harness above, its round trip by the property tests.

/// VER-1 for `sample.Strict`: an ordinal no message has is
/// refused by the validator, which `decode_exact` runs first,
/// whatever follows it (bounds: 2 to 4 bytes).
#[cfg(kani)]
#[kani::proof]
#[kani::unwind(6)]
fn verify_strict_unknown_ordinal() {
    let ordinal: u16 = kani::any_where(|&n: &u16| usize::from(n) >= 3);
    let tail: [u8; 2] = kani::any();
    let len: usize = kani::any_where(|&n: &usize| (2..=4).contains(&n));
    let [o0, o1] = ordinal.to_le_bytes();
    let [t0, t1] = tail;
    let bytes = [o0, o1, t0, t1];
    let Some(input) = bytes.get(..len) else {
        return;
    };
    assert!(Strict::validate_bytes(input) == Err(BadMessage::UnknownOrdinal));
}

/// A free interface that drops on overflow.
///
/// Interface `sample.Loose`: free, capacity 1024, overflow `drop`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Loose {
    /// A single byte, the smallest message with a payload.
    Tick {
        /// The byte.
        value: u8,
    },
    /// An optional event.
    MaybeEvent {
        /// The event, if any.
        event: Option<Event>,
    },
}

impl Loose {
    /// What the `.hgidl` declared about this interface.
    pub const INFO: hg_ipc::InterfaceInfo = hg_ipc::InterfaceInfo {
        name: "sample.Loose",
        binding: hg_ipc::Binding::Free,
        capacity: 1024,
        overflow: hg_ipc::Overflow::Drop,
        max_message_len: hg_ipc::wire::len_add(
            2,
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_add(0, <u8 as Wire>::MAX_LEN),
                hg_ipc::wire::len_add(0, <Option<Event> as Wire>::MAX_LEN),
            ),
        ),
    };
}

impl Loose {
    /// Reads [`Self::Tick`]'s fields, after its ordinal.
    fn decode_tick(r: &mut Reader<'_>) -> Result<(u8,), BadMessage> {
        Ok((Wire::decode(r)?,))
    }
    /// Checks [`Self::Tick`]'s fields, after its ordinal.
    fn validate_tick(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <u8 as Wire>::validate(r)?;
        Ok(())
    }
    /// Writes [`Self::Tick`]'s fields, after its ordinal.
    fn encode_tick(w: &mut Writer, value: &u8) {
        value.encode(w);
    }
    /// Reads [`Self::MaybeEvent`]'s fields, after its ordinal.
    fn decode_maybe_event(r: &mut Reader<'_>) -> Result<(Option<Event>,), BadMessage> {
        Ok((Wire::decode(r)?,))
    }
    /// Checks [`Self::MaybeEvent`]'s fields, after its ordinal.
    fn validate_maybe_event(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <Option<Event> as Wire>::validate(r)?;
        Ok(())
    }
    /// Writes [`Self::MaybeEvent`]'s fields, after its ordinal.
    fn encode_maybe_event(w: &mut Writer, event: &Option<Event>) {
        event.encode(w);
    }
}

impl Wire for Loose {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Tick { value } => {
                0u16.encode(w);
                Self::encode_tick(w, value);
            }
            Self::MaybeEvent { event } => {
                1u16.encode(w);
                Self::encode_maybe_event(w, event);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u16::decode(r)? {
            0 => {
                let (value,) = Self::decode_tick(r)?;
                Ok(Self::Tick { value })
            }
            1 => {
                let (event,) = Self::decode_maybe_event(r)?;
                Ok(Self::MaybeEvent { event })
            }
            _ => Err(BadMessage::UnknownOrdinal),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u16::decode(r)? {
            0 => Self::validate_tick(r),
            1 => Self::validate_maybe_event(r),
            _ => Err(BadMessage::UnknownOrdinal),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        2,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_add(0, <u8 as Wire>::MIN_LEN),
            hg_ipc::wire::len_add(0, <Option<Event> as Wire>::MIN_LEN),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        2,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_add(0, <u8 as Wire>::MAX_LEN),
            hg_ipc::wire::len_add(0, <Option<Event> as Wire>::MAX_LEN),
        ),
    );
}

impl Loose {
    /// Checks that `bytes` are one valid message, allocating nothing.
    ///
    /// # Errors
    /// [`BadMessage`] if they are not.
    pub fn validate_bytes(bytes: &[u8]) -> Result<(), BadMessage> {
        let mut r = Reader::new(bytes);
        match u16::decode(&mut r)? {
            0 => Self::validate_tick(&mut r)?,
            1 => Self::validate_maybe_event(&mut r)?,
            _ => return Err(BadMessage::UnknownOrdinal),
        }
        r.finish()
    }
}

impl hg_ipc::Interface for Loose {
    const INFO: hg_ipc::InterfaceInfo = Self::INFO;
    fn into_wire(self) -> (Vec<u8>, Vec<hg_ipc::Handle>) {
        let mut w = Writer::new();
        match self {
            Self::Tick { value } => {
                0u16.encode(&mut w);
                Self::encode_tick(&mut w, &value);
            }
            Self::MaybeEvent { event } => {
                1u16.encode(&mut w);
                Self::encode_maybe_event(&mut w, &event);
            }
        }
        (w.into_bytes(), Vec::new())
    }
    fn from_wire(
        bytes: &[u8],
        handles: Vec<hg_ipc::Handle>,
        ipc: &std::sync::Arc<dyn hg_ipc::Ipc>,
    ) -> Result<Self, BadMessage> {
        let _ = ipc;
        // Every check before any decoding: the bytes by the validator,
        // which allocates nothing, then the handles' kinds (IPC-R1).
        Self::validate_bytes(bytes)?;
        let mut r = Reader::new(bytes);
        let msg = match u16::decode(&mut r)? {
            0 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (value,) = Self::decode_tick(&mut r)?;
                Self::Tick { value }
            }
            1 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (event,) = Self::decode_maybe_event(&mut r)?;
                Self::MaybeEvent { event }
            }
            _ => return Err(BadMessage::UnknownOrdinal),
        };
        r.finish()?;
        Ok(msg)
    }
}

impl hg_ipc::FreeInterface for Loose {}

/// Receives `sample.Loose`'s messages, each already checked. An `Err`
/// closes the endpoint and reports the sender (IPC-R5).
pub trait LooseHandler {
    /// A single byte, the smallest message with a payload.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn tick(&mut self, value: u8) -> Result<(), SampleError>;
    /// An optional event.
    ///
    /// # Errors
    /// The protocol's error, which ends the conversation.
    fn maybe_event(&mut self, event: Option<Event>) -> Result<(), SampleError>;
}

impl Loose {
    /// Passes this message to its handler method.
    ///
    /// # Errors
    /// The handler's.
    pub fn dispatch<H: LooseHandler + ?Sized>(self, h: &mut H) -> Result<(), SampleError> {
        match self {
            Self::Tick { value } => h.tick(value),
            Self::MaybeEvent { event } => h.maybe_event(event),
        }
    }
}

/// Sends `sample.Loose`'s messages; implemented for `hg_ipc::Remote<Loose>`.
pub trait LooseRemote {
    /// A single byte, the smallest message with a payload.
    ///
    /// # Errors
    /// [`hg_ipc::SendError`]; the sender never blocks.
    fn tick(&self, value: u8) -> Result<(), hg_ipc::SendError>;
    /// An optional event.
    ///
    /// # Errors
    /// [`hg_ipc::SendError`]; the sender never blocks.
    fn maybe_event(&self, event: Option<Event>) -> Result<(), hg_ipc::SendError>;
}

impl LooseRemote for hg_ipc::Remote<Loose> {
    fn tick(&self, value: u8) -> Result<(), hg_ipc::SendError> {
        self.send(Loose::Tick { value })
    }
    fn maybe_event(&self, event: Option<Event>) -> Result<(), hg_ipc::SendError> {
        self.send(Loose::MaybeEvent { event })
    }
}

#[cfg(test)]
impl crate::sample::Sample for Loose {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        use crate::sample::Sample;
        match g.below(2) {
            0 => Self::Tick {
                value: Sample::sample(g),
            },
            _ => Self::MaybeEvent {
                event: Sample::sample(g),
            },
        }
    }
}

